// ═══════════════════════════════════════════════════════════════
//  BUILD OLLAMA REQUEST (REFINED v5 — 2 SERielle LÄUFE DE + EN)
//
//  NEU in v5:
//   - 2 separate Ollama-Läufe (DE zuerst, dann EN) SERIELL
//     → entlastet CPU (kein paralleler Ollama-Stress)
//     → entlastet Qwen (nur 10 Items pro Run statt 20)
//     → kein Ermüdungseffekt bei letzten Items
//   - DE-Run schreibt summaryDe + alle DE-Items (headlineEn als Übersetzung)
//   - EN-Run schreibt summaryEn + alle EN-Items (headlineDe als Übersetzung)
//   - Merge: kombiniert DE-Result + EN-Result zu einem JSON für Ingest
//   - Partial-Failure: wenn ein Run failed, wird der andere trotzdem gespeichert
//
//  Beibehalten aus v4:
//   - this.helpers.httpRequest (n8n Expression-Parser Workaround)
//   - enable_thinking: false (verhindert Token-Verschwendung)
//   - 600s Timeout pro Run (CPU-Inference)
//   - Leaner Prompt (nur title, source, language, summary)
//
//  Node-Typ: Code (n8n)
//  Position: nach "Score & Rank", vor "Parse LLM JSON"
// ═══════════════════════════════════════════════════════════════

const allItems = $input.all();

// ── Fallback: Keine Items → Fehler mit Kontext ─────────────────
if (!allItems || allItems.length === 0) {
  throw new Error('Build Ollama: Keine Items vom Score&Rank-Node erhalten. Prüfe RSS-Feeds und Score&Rank.');
}

const newsItems = allItems.map(function(i) {
  return {
    title: i.json.title || '',
    link: i.json.link || '',
    source: i.json.source || '',
    summary: i.json.summary || '',
    languageOrig: i.json.languageOrig || 'en',
    bucket: i.json._bucket || 'en'
  };
});

// Nach Bucket gruppieren
const deItems = newsItems.filter(i => i.bucket === 'de');
const enItems = newsItems.filter(i => i.bucket === 'en');

console.log(`[Build Ollama v5] ${newsItems.length} Items für 2 Läufe (DE=${deItems.length}, EN=${enItems.length})`);

// ═══════════════════════════════════════════════════════════════
//  HELPER: Ollama-Call für einen Bucket
// ═══════════════════════════════════════════════════════════════

async function callOllama(items, bucket) {
  if (items.length === 0) {
    console.log(`[Build Ollama v5] ${bucket}-Run übersprungen (keine Items)`);
    return null;
  }

  const isDe = bucket === 'de';

  // ── System Prompt (sprachspezifisch) ────────────────────────
  // DE-Run: schreibt summaryDe + headlineEn (Übersetzung DE→EN)
  // EN-Run: schreibt summaryEn + headlineDe (Übersetzung EN→DE)
  //
  // WICHTIG: Kleine Modelle (2B) neigen dazu, JSON-Output früh
  // abzuschließen wenn sie "denken" es reicht. Deshalb:
  // 1. Explizite Ansage: "Process ALL N items, do not stop early"
  // 2. Item-Nummerierung im User-Prompt (Qwen sieht: "Item 1 von 10")
  // 3. "format: json_object" in Ollama-Options (erzwingt JSON-Mode)
  const systemPrompt = isDe
    ? `You are an expert AI news curator for Levcon.ai, a Vienna-based AI consulting firm.

Your task: Process ALL ${items.length} GERMAN AI news items from DACH sources. You MUST process every single item — do NOT stop early, do NOT skip items, do NOT truncate the output. Use standard Latin script. Do not use Chinese, Japanese, Korean, Cyrillic, or any other non-Latin characters under any circumstances.
For each item, write:
- headline: Original German headline (keep as-is)
- headlineDe: Same as headline (it's already German)
- headlineEn: English translation of the headline (natural, not literal)
- descriptionDe: 1-2 sentence German summary (analytical)
- descriptionEn: 1-2 sentence English summary (independent, not just translation)
- source, sourceUrl, thumbnailUrl, languageOrig, category (research|business|regulation|tools|society)

Also write summaryDe: Analytische Zusammenfassung der heutigen  KI-News (3-4 Sätze).

Summary tone: Professional, concise.

Return JSON:
{
  "summaryDe": "...",
  "items": [
    { "headline": "...", "headlineDe": "...", "headlineEn": "...", "descriptionDe": "...", "descriptionEn": "...", "source": "...", "sourceUrl": "...", "thumbnailUrl": null, "languageOrig": "de", "category": "..." }
  ]
}

CRITICAL: You MUST return ALL ${items.length} items in the items array. If you return fewer, the workflow will fail. Process every item, then close the JSON with } and ].`
    : `You are an expert AI news curator for Levcon.ai, a Vienna-based AI consulting firm.

Your task: Process ALL ${items.length} ENGLISH AI news items from international sources. You MUST process every single item — do NOT stop early, do NOT skip items, do NOT truncate the output. Use standard Latin script. Do not use Chinese, Japanese, Korean, Cyrillic, or any other non-Latin characters under any circumstances.

For each item, write:
- headline: Original English headline (keep as-is)
- headlineDe: German translation of the headline (natural, not literal)
- headlineEn: Same as headline (it's already English)
- descriptionDe: 1-2 sentence German summary (analytical, not just translation)
- descriptionEn: 1-2 sentence English summary (independent)
- source, sourceUrl, thumbnailUrl, languageOrig, category (research|business|regulation|tools|society)

Also write summaryEn: Analytical summary of today's international AI news (3-4 sentences).

Summary tone: Professional, concise.

Return JSON:
{
  "summaryEn": "...",
  "items": [
    { "headline": "...", "headlineDe": "...", "headlineEn": "...", "descriptionDe": "...", "descriptionEn": "...", "source": "...", "sourceUrl": "...", "thumbnailUrl": null, "languageOrig": "en", "category": "..." }
  ]
}

CRITICAL: You MUST return ALL ${items.length} items in the items array. If you return fewer, the workflow will fail. Process every item, then close the JSON with } and ].`;

  // ── User Prompt (mit Item-Nummerierung für bessere Vollständigkeit) ──
  // Item 1/N, 2/N, ... — das hilft Qwen zu sehen wie viele Items kommen
  // und nicht mittendrin abzubrechen.
  const itemsNumbered = items.map((i, idx) => ({
    [`Item ${idx + 1} of ${items.length}`]: {
      title: i.title,
      link: i.link,
      source: i.source,
      language: i.languageOrig,
      summary: i.summary.substring(0, 120)
    }
  }));

  const userPrompt = `${bucket} ITEMS (${items.length} total — process ALL ${items.length}):
${JSON.stringify(itemsNumbered, null, 2)}

Process EVERY item from 1 to ${items.length}. Do not stop after item 6 or 7. Output ALL ${items.length} items in the JSON array.`;

  // ── Request Body (v5.1: format=json_object erzwingt JSON-Output) ──
  // format: "json_object" zwingt Ollama/Qwen zu validem JSON — verhindert
  // dass Qwen mittendrin abbricht und invalides JSON zurückgibt.
  // num_predict: 6144 als Sicherheitspuffer (10 Items × 5 Felder ≈ 3.200 Tokens
  // + summary ~200 + JSON-Overhead ~300 = ~3.700, Puffer bis 6144)
  const requestBody = {
    model: "qwen3.5:2b",
    stream: false,
    format: "json_object",   // NEU: erzwingt JSON-Mode (verhindert early abort)
    options: {
      temperature: 0.3,
      num_predict: 6144,      // v5.1: erhöht von 4096 (Sicherheitspuffer)
      num_ctx: 32768,
      enable_thinking: false
    },
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ],
    "think": false
  };

  console.log(`[Build Ollama v5] ${bucket}-Run startet (${items.length} Items, num_predict=6144, format=json_object)`);
  const runStart = Date.now();

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:11434/api/chat',
    headers: { 'Content-Type': 'application/json' },
    body: requestBody,
    json: true,
    timeout: 600000  // 10min für CPU-Inference
  });

  const duration = ((Date.now() - runStart) / 1000).toFixed(1);
  console.log(`[Build Ollama v5] ${bucket}-Run fertig in ${duration}s (${response.message?.content?.length || 0} chars)`);

  return response;
}

// ═══════════════════════════════════════════════════════════════
//  MAIN: 2 SERIELLE LÄUFE (DE zuerst, dann EN)
// ═══════════════════════════════════════════════════════════════
//  Seriell weil:
//  - Ollama auf CPU nicht gut parallel kann (RLY belastet)
//  - Qwen-Modell wird beim 2. Run aus RAM geladen (schneller)
//  - Einfacher zu debuggen, klare Reihenfolge im Log

let deResult = null;
let enResult = null;
const errors = [];

// 1. DE-Run
try {
  deResult = await callOllama(deItems, 'de');
} catch (err) {
  console.error(`[Build Ollama v5] ❌ DE-Run failed: ${err.message}`);
  errors.push({ run: 'de', error: err.message });
}

// 2. EN-Run (nur starten wenn DE fertig — seriell)
try {
  enResult = await callOllama(enItems, 'en');
} catch (err) {
  console.error(`[Build Ollama v5] ❌ EN-Run failed: ${err.message}`);
  errors.push({ run: 'en', error: err.message });
}

// 3. Beide Runs failed → harter Fehler
if (!deResult && !enResult) {
  throw new Error(`Build Ollama v5: Beide Läufe failed. Errors: ${JSON.stringify(errors)}`);
}

// 4. Parse + Merge: kombiniere DE-Result + EN-Result
//    Der Parse LLM JSON Node weiter unten erwartet { message: { content: "..." } }
//    Wir bauen hier ein synthetisches Response-Objekt das beide Runs merged.

function extractContent(resp) {
  if (!resp) return null;
  if (resp.message && resp.message.content) return resp.message.content;
  if (resp.choices && resp.choices[0] && resp.choices[0].message) return resp.choices[0].message.content;
  if (resp.response) return resp.response;
  return null;
}

function parseJson(content) {
  if (!content) return null;
  // Clean markdown
  let cleaned = content.replace(/```json\n/g, '').replace(/```\n/g, '').replace(/```/g, '').trim();
  // Auto-Repair: fehlende Kommas
  cleaned = cleaned.replace(/"\s*\n\s*"/g, '",\n"');
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { return null; }
    }
    return null;
  }
}

const deJson = parseJson(extractContent(deResult));
const enJson = parseJson(extractContent(enResult));

console.log(`[Build Ollama v5] Parse: DE=${deJson ? 'OK' : 'FAIL'}, EN=${enJson ? 'OK' : 'FAIL'}`);

// ═══════════════════════════════════════════════════════════════
//  5. ENRICHMENT: LLM-Items mit Originaldaten anreichern
// ═══════════════════════════════════════════════════════════════
//  Qwen3.5:2b vergisst manchmal Felder (source, sourceUrl, languageOrig)
//  besonders bei den letzten Items (Ermüdungseffekt). Wir reichern
//  jedes LLM-Item mit den Originaldaten an, damit Prisma nie
//  "Argument source is missing" wirft.
//
//  Matching: LLM-Item.sourceUrl === Original-Item.link
//  Falls kein Match (LLM hat URL vergessen): versuche Match via headline.
//  Falls immer noch kein Match: behalte LLM-Daten, fülle Pflichtfelder
//  mit Fallbacks.

function enrichItems(llmItems, originalItems, defaultLang) {
  if (!llmItems || !Array.isArray(llmItems)) return [];

  // Lookup-Map: sourceUrl → originalItem (für schnelles Matchen)
  const byUrl = new Map();
  const byTitle = new Map();
  for (const orig of originalItems) {
    if (orig.link) byUrl.set(orig.link, orig);
    if (orig.title) byTitle.set(orig.title.toLowerCase().trim(), orig);
  }

  const enriched = [];
  const dropped = [];

  for (const item of llmItems) {
    // Versuche Match via sourceUrl (bevorzugt) oder headline (Fallback)
    let original = null;
    if (item.sourceUrl && byUrl.has(item.sourceUrl)) {
      original = byUrl.get(item.sourceUrl);
    } else if (item.headline) {
      // Versuche exakte Titel-Match
      const key = (item.headline || '').toLowerCase().trim();
      if (byTitle.has(key)) {
        original = byTitle.get(key);
      } else {
        // Versuche Titel-Match via erste 50 Zeichen (Qwen might have shortened)
        for (const [titleKey, origItem] of byTitle) {
          if (titleKey.includes(key.substring(0, 50)) || key.includes(titleKey.substring(0, 50))) {
            original = origItem;
            break;
          }
        }
      }
    }

    // KEIN Match gefunden → Item verwerfen (verhindert "Unknown" Items im Frontend)
    // Diese Items haben keine verlässliche sourceUrl und würden die Archiv-Suche
    // und das Frontend verfälschen. Besser weglassen als Müll zeigen.
    if (!original) {
      dropped.push({
        headline: (item.headline || '').substring(0, 60),
        reason: 'no match to original input'
      });
      continue;
    }

    // Enrichment: LLM-Daten haben Vorrang, aber wenn Feld fehlt → Original
    enriched.push({
      headline: item.headline || original.title,
      headlineDe: item.headlineDe || item.headline || original.title || null,
      headlineEn: item.headlineEn || item.headline || original.title || null,
      descriptionDe: item.descriptionDe || 'Keine Zusammenfassung verfügbar.',
      descriptionEn: item.descriptionEn || 'No summary available.',
      source: item.source || original.source,
      sourceUrl: item.sourceUrl || original.link,
      thumbnailUrl: item.thumbnailUrl || null,
      languageOrig: item.languageOrig || original.languageOrig || defaultLang,
      category: item.category || null,
    });
  }

  if (dropped.length > 0) {
    console.log(`[Build Ollama v5] ⚠️ ${dropped.length} Items verworfen (kein Match zu Original-Input):`);
    dropped.forEach(d => console.log(`   - "${d.headline}..." (${d.reason})`));
  }

  return enriched;
}

const deItemsEnriched = enrichItems(deJson?.items, deItems, 'de');
const enItemsEnriched = enrichItems(enJson?.items, enItems, 'en');

// Logging: Item-Count-Check (Qwen könnte Items vergessen haben)
console.log(`[Build Ollama v5] Item-Count: DE-Input=${deItems.length}, DE-Output=${deItemsEnriched.length}${deItems.length !== deItemsEnriched.length ? ' ⚠️ MISMATCH' : ''}`);
console.log(`[Build Ollama v5] Item-Count: EN-Input=${enItems.length}, EN-Output=${enItemsEnriched.length}${enItems.length !== enItemsEnriched.length ? ' ⚠️ MISMATCH' : ''}`);

// 6. Merge zu kombiniertem JSON
const mergedJson = {
  summaryDe: deJson?.summaryDe || '',
  summaryEn: enJson?.summaryEn || '',
  items: [
    ...deItemsEnriched,
    ...enItemsEnriched
  ]
};

console.log(`[Build Ollama v5] Merge: ${mergedJson.items.length} Items (DE=${deItemsEnriched.length}, EN=${enItemsEnriched.length})`);
console.log(`[Build Ollama v5] summaryDe: ${mergedJson.summaryDe ? '✓' : '✗'}, summaryEn: ${mergedJson.summaryEn ? '✓' : '✗'}`);

// Validierung: jedes Item muss source und sourceUrl haben
const missingSource = mergedJson.items.filter(i => !i.source);
const missingUrl = mergedJson.items.filter(i => !i.sourceUrl);
if (missingSource.length > 0 || missingUrl.length > 0) {
  console.log(`[Build Ollama v5] ⚠️ Validierung: ${missingSource.length} Items ohne source, ${missingUrl.length} ohne sourceUrl`);
}

if (errors.length > 0) {
  console.log(`[Build Ollama v5] ⚠️ Partial failure: ${errors.map(e => e.run).join(', ')} failed but other run succeeded`);
}

// 7. Return: direkt das geparste JSON-Objekt zurückgeben.
//    WICHTIG: Der Build Ollama v5 Node hat bereits:
//    - Ollama-Call gemacht
//    - JSON geparst (mit Auto-Repair)
//    - Items mit Originaldaten angereichert (Enrichment)
//    - Zu einem gemergeden JSON kombiniert
//
//    Ein separater "Parse LLM JSON" Node ist NICHT MEHR NÖTIG.
//    Dieser Node gibt direkt das fertige Objekt zurück, das die Ingest-API
//    erwartet: { summaryDe, summaryEn, items[] }
//
//    Falls der alte "Parse LLM JSON" Node noch in der Workflow-Canvas
//    existiert, kann er GELÖSCHT werden. Die Ingest-API direkt nach
//    Build Ollama verbinden.
//
//    Alternativ: Falls der Parse Node als Validierungs-Passthrough
//    erhalten bleiben soll, muss sein Code angepasst werden auf:
//    return items;  (einfach durchreichen)
return [{ json: mergedJson }];

// ═══════════════════════════════════════════════════════════════
//  FETCH ALL RSS FEEDS (v4 — Encoding-Fix FINAL)
//
//  Root-Cause:
//   this.helpers.httpRequest dekodiert Body intern immer als UTF-8.
//   Fix: helpers.request() (request-Library) mit encoding:null liefert
//        echten Buffer → korrektes Charset-Erkennung & Dekodierung.
//   Fallback: native fetch() mit AbortController (NICHT AbortSignal.timeout,
//             das erst ab Node 17.3 existiert).
//
//  Node-Typ: Code (n8n)
//  Position im Workflow: nach Schedule Trigger, vor "Dedupe by URL"
// ═══════════════════════════════════════════════════════════════

// ── KONFIGURATION ──────────────────────────────────────────────
const MAX_ITEMS_PER_FEED = 30;
const FETCH_TIMEOUT_MS   = 30000;
const FETCH_RETRIES      = 2;
// ──────────────────────────────────────────────────────────────

// n8n-Kontext einmal oben sichern — helper-Funktionen haben kein 'this'
const _helpers = this.helpers;

const RSS_FEEDS = [
  // 🇩🇪 Deutsch (10)
  { url: 'https://www.heise.de/rss/heise-atom.xml',              source: 'Heise',               lang: 'de' },
  { url: 'https://rss.golem.de/rss.php?feed=RSS2.0',             source: 'Golem',               lang: 'de' },
  { url: 'https://www.tagesschau.de/xml/rss2',                   source: 'Tagesschau',          lang: 'de' },
  { url: 'https://rss.sueddeutsche.de/rss/wissen',               source: 'Süddeutsche Zeitung', lang: 'de' },
  { url: 'https://mixed.de/feed/',                               source: 'Mixed.de',            lang: 'de' },
  { url: 'https://ainauten.com/feed/',                           source: 'AInauten',            lang: 'de' },
  { url: 'https://www.derstandard.at/rss/web/tech',              source: 'Der Standard',        lang: 'de' },
  { url: 'https://www.zdnet.de/feed/',                           source: 'ZDNet',               lang: 'de' },
  { url: 'https://www.netzwelt.de/feed/',                        source: 'Netzwelt',            lang: 'de' },
  { url: 'https://www.ki-campus.org/rss',                        source: 'KI-Campus',           lang: 'de' },

  // 🇺🇸 Englisch (12)
  { url: 'https://www.technologyreview.com/feed/',               source: 'MIT Tech Review',     lang: 'en' },
  { url: 'https://feeds.arstechnica.com/arstechnica/features',   source: 'Ars Technica',        lang: 'en' },
  { url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml', source: 'The Verge', lang: 'en' },
  { url: 'https://techcrunch.com/category/artificial-intelligence/feed/', source: 'TechCrunch', lang: 'en' },
  { url: 'https://venturebeat.com/category/ai/feed/',            source: 'VentureBeat',         lang: 'en' },
  { url: 'https://www.marktechpost.com/feed/',                   source: 'MarkTechPost',        lang: 'en' },
  { url: 'https://huggingface.co/blog/feed.xml',                 source: 'Hugging Face',        lang: 'en' },
  { url: 'https://www.anthropic.com/news/rss.xml',               source: 'Anthropic',           lang: 'en' },
  { url: 'https://openai.com/blog/rss.xml',                      source: 'OpenAI',              lang: 'en' },
  { url: 'https://www.wired.com/feed/tag/ai/latest/rss',         source: 'Wired',               lang: 'en' },
  { url: 'https://towardsdatascience.com/feed',                  source: 'Towards Data Science', lang: 'en' },
  { url: 'https://www.theinformation.com/feed',                  source: 'The Information',     lang: 'en' },

  // 🇨🇳 Chinesisch (4)
  { url: 'https://syncedreview.com/feed/',                       source: 'Synced',              lang: 'zh' },
  { url: 'https://www.caixinglobal.com/feed/',                   source: 'Caixin Global',       lang: 'zh' },
  { url: 'https://pandaily.com/feed/',                           source: 'Pandaily',            lang: 'zh' },
  { url: 'https://technode.com/feed/',                           source: 'TechNode',            lang: 'zh' },

  // 🇯🇵 Japanisch (3)
  { url: 'https://rss.itmedia.co.jp/rss/2.0/news_bursts.xml',   source: 'ITmedia',             lang: 'ja' },
  { url: 'https://tech.nikkeibp.co.jp/rss/index.rdf',           source: 'Nikkei Tech',         lang: 'ja' },
  { url: 'https://ascii.jp/rss.xml',                             source: 'ASCII.jp',            lang: 'ja' },

  // 🇫🇷 Französisch (3)
  { url: 'https://www.usine-digitale.fr/rss/index.xml',          source: "L'Usine Digitale",    lang: 'fr' },
  { url: 'https://www.journaldunet.com/rss/',                    source: 'Le Journal du Net',   lang: 'fr' },
  { url: 'https://actuia.com/feed/',                             source: 'ActuIA',              lang: 'fr' },

  // 🌐 Research (3)
  { url: 'https://export.arxiv.org/api/query?search_query=cat:cs.AI&sortBy=submittedDate&sortOrder=descending&max_results=10', source: 'arXiv cs.AI', lang: 'en' },
  { url: 'https://export.arxiv.org/api/query?search_query=cat:cs.LG&sortBy=submittedDate&sortOrder=descending&max_results=10', source: 'arXiv cs.LG', lang: 'en' },
  { url: 'https://export.arxiv.org/api/query?search_query=cat:cs.CL&sortBy=submittedDate&sortOrder=descending&max_results=10', source: 'arXiv cs.CL', lang: 'en' }
